nppx.registerCommand("community.html.preview", () => {
  const raw = nppx.getActiveText();
  if (!raw.trim()) {
    nppx.notify("Nothing to preview");
    return;
  }
  nppx.openPreview({
    title: "HTML Preview — " + (nppx.getActiveFileName() || "untitled"),
    html: raw,
  });
});
nppx.registerCommand("community.html.previewClose", () => {
  nppx.closePreview();
});
